-- 172: Original BrillaPrep WASSCE BrillaPrep transitional Metalwork beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_172_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_172_guard;
INSERT INTO _migration_172_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_001' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_1' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which eye protection is appropriate when using a bench grinder?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Impact-rated safety goggles or a face shield with safety glasses","B. Tinted fashion spectacles without side protection","C. A welding helmet with no clear viewing option","D. No protection when the wheel guard is fitted"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Abrasive wheels can eject particles or fragments at high speed, so rated eye and face protection supplements guards and safe tool-rest adjustment. Therefore the correct answer is A: Impact-rated safety goggles or a face shield with safety glasses.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_001' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_172_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_002' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_1' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a surface plate in marking-out work?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cut internal threads in drilled holes","B. Provide a flat reference plane for accurate measurements","C. Harden steel by rapid cooling","D. Support hot metal during forging"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A verified flat surface allows heights, angles and datum lines to be transferred consistently with gauges and marking tools. Therefore the correct answer is B: Provide a flat reference plane for accurate measurements.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_002' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_172_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_003' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_1' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which instrument is most suitable for checking a shaft diameter to 0.01 mm?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A steel rule","B. A try square","C. An outside micrometer","D. A centre punch"]' AND q.correct_answer IS 'C' AND q.explanation IS 'An outside micrometer uses a precision screw and calibrated scale to measure external dimensions more accurately than general layout tools. Therefore the correct answer is C: An outside micrometer.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_003' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_172_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_004' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_1' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a centre punch mark made before drilling?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Enlarge the finished hole to final size","B. Cut a countersink around the hole","C. Measure the hardness of the material","D. Locate the drill point and reduce wandering at the start"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The conical indentation guides the drill chisel edge so the hole begins at the intended marked position. Therefore the correct answer is D: Locate the drill point and reduce wandering at the start.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_004' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_172_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_005' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_1' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should be done before measuring a freshly machined part with a precision instrument?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Remove burrs and allow a hot part to approach reference temperature","B. Measure across attached swarf to save time","C. Oil the scale until graduations disappear","D. Strike the micrometer frame against the work"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Burrs distort contact and heat changes dimensions, so clean stable surfaces are necessary for a meaningful precision reading. Therefore the correct answer is A: Remove burrs and allow a hot part to approach reference temperature.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_005' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
